class Rectangle:
    def __init__(self, a, b=-1):
        if b == -1:
            self.side = a
            self.area = a * a
        else:
            self.length = a
            self.width = b
            self.area = a * b

def main():
    import sys
    data = sys.stdin.read().strip().split()
    a = int(data[0])
    b = int(data[1]) if len(data) > 1 else -1
    rect = Rectangle(a, b)
    print(rect.area)

if __name__ == "__main__":
    main()
